// DecodeSetFreq decodes a SetFreq from data, a frame of 9, 10 or 14 octets.
// It returns ErrShort when data is shorter than 9 octets and ErrLength when
// its length is not one of these. It does not keep data.
func DecodeSetFreq(data []byte) (SetFreq, error) {
	switch len(data) {
	case 9, 10, 14:
	default:
		if len(data) < 9 {
			return SetFreq{}, ErrShort
		}
		return SetFreq{}, ErrLength
	}
	var result SetFreq
	result.Size = uint8(len(data))
	result.Reserved = uint8(uint64(data[0]))
	var _vRX uint64
	_vRX = uint64(data[1]) | uint64(data[2])<<8 | uint64(data[3])<<16 | uint64(data[4])<<24
	result.RX = uint32(_vRX)
	var _vTX uint64
	_vTX = uint64(data[5]) | uint64(data[6])<<8 | uint64(data[7])<<16 | uint64(data[8])<<24
	result.TX = uint32(_vTX)
	if len(data) >= 10 {
		result.RFLevel = uint8(uint64(data[9]))
	}
	if len(data) >= 14 {
		var _vPOCSAG uint64
		_vPOCSAG = uint64(data[10]) | uint64(data[11])<<8 | uint64(data[12])<<16 | uint64(data[13])<<24
		result.POCSAG = uint32(_vPOCSAG)
	}
	return result, nil
}

// AppendBinary appends the 9, 10 or 14 octets of s to dst: Size selects the
// length, and 0 means 9. It returns dst unchanged and a
// *dmrgo.FieldRangeError when a field does not fit, or an error when Size is
// not one of the lengths. It allocates only to grow dst.
func (s *SetFreq) AppendBinary(dst []byte) ([]byte, error) {
	_n := len(dst)
	_size := 9
	switch s.Size {
	case 0, 9:
	case 10:
		_size = 10
	case 14:
		_size = 14
	default:
		return dst, errSetFreqSize
	}
	for range _size {
		dst = append(dst, 0)
	}
	data := dst[_n:]
	data[0] = byte(uint64(s.Reserved))
	_vRX := uint64(s.RX)
	data[1] = byte(_vRX)
	data[2] = byte(_vRX >> 8)
	data[3] = byte(_vRX >> 16)
	data[4] = byte(_vRX >> 24)
	_vTX := uint64(s.TX)
	data[5] = byte(_vTX)
	data[6] = byte(_vTX >> 8)
	data[7] = byte(_vTX >> 16)
	data[8] = byte(_vTX >> 24)
	if _size >= 10 {
		data[9] = byte(uint64(s.RFLevel))
	}
	if _size >= 14 {
		_vPOCSAG := uint64(s.POCSAG)
		data[10] = byte(_vPOCSAG)
		data[11] = byte(_vPOCSAG >> 8)
		data[12] = byte(_vPOCSAG >> 16)
		data[13] = byte(_vPOCSAG >> 24)
	}
	return dst, nil
}

// String returns the fields of s as text, for printing. It allocates the
// string.
func (s *SetFreq) String() string {
	return "SetFreq{ Reserved: " + text.Int(int64(s.Reserved)) + ", RX: " + text.Int(int64(s.RX)) + ", TX: " + text.Int(int64(s.TX)) + ", RFLevel: " + text.Int(int64(s.RFLevel)) + ", POCSAG: " + text.Int(int64(s.POCSAG)) + " }"
}

// DecodeSetMode decodes a SetMode from data, a frame of 1 octet. It returns
// ErrShort when data is shorter than 1 octet and ErrLength when it is
// longer. It does not keep data.
func DecodeSetMode(data []byte) (SetMode, error) {
	if len(data) < 1 {
		return SetMode{}, ErrShort
	}
	if len(data) != 1 {
		return SetMode{}, ErrLength
	}
	var result SetMode
	result.Mode = Mode(uint64(data[0]))
	return result, nil
}

// AppendBinary appends the 1 octet of s to dst. It returns dst unchanged and
// a *dmrgo.FieldRangeError when a field does not fit. It allocates only to
// grow dst.
func (s *SetMode) AppendBinary(dst []byte) ([]byte, error) {
	_n := len(dst)
	for range 1 {
		dst = append(dst, 0)
	}
	data := dst[_n:]
	data[0] = byte(uint64(s.Mode))
	return dst, nil
}

// String returns the fields of s as text, for printing. It allocates the
