// DecodeDMRShortLC decodes a DMRShortLC from data, a frame of 9 octets. It
// returns ErrShort when data is shorter than 9 octets and ErrLength when it
// is longer. It does not keep data.
func DecodeDMRShortLC(data []byte) (DMRShortLC, error) {
	if len(data) < 9 {
		return DMRShortLC{}, ErrShort
	}
	if len(data) != 9 {
		return DMRShortLC{}, ErrLength
	}
	var result DMRShortLC
	copy(result.LC[0:9], data[0:9])
	return result, nil
}

// AppendBinary appends the 9 octets of s to dst. It returns dst unchanged
// and a *dmrgo.FieldRangeError when a field does not fit. It allocates only
// to grow dst.
